  void BuildCabin(int tower,bool backdrop,int style){ChapterSky(tower);LiftArchitecture.Cabin(_scene.transform);LiftArchitecture.Rails(_scene.transform);var cabin=_scene.transform.Find("CopperLiftCabin");float shift=backdrop?-1.4f:0;cabin.localPosition=new Vector3(shift,0,0);foreach(Transform child in _scene.transform)if(child.name=="VerticalLiftRail"||child.name=="CopperRailGuide"||child.name=="RailMount")child.localPosition+=Vector3.right*shift;
