   var stone=MeshArt.Mat("LobbyMarble",new Color(.78f,.76f,.67f));MeshArt.Lathe(_scene.transform,"LobbyLanding",new[]{.47f,.60f},new[]{1.15f,1.15f},48,FloorArchitecturePalette.Get(_scene.transform,FloorArchitectureSurface.Deck),new Vector3(1,1,.80f)).transform.localPosition=Vector3.right*shift;MeshArt.Box(_scene.transform,"AtriumMarbleFloor",new Vector3(0,.10f,2.4f),new Vector3(13,.15f,8),stone);var inlay=MeshArt.Mat("LobbyFloorInlay",new Color(.09f,.29f,.29f));for(int i=0;i<6;i++)MeshArt.Box(_scene.transform,"AtriumFloorInlay",new Vector3(-5+i*2,.19f,2.4f),new Vector3(.035f,.01f,8),inlay);
   if(backdrop)LiftAtriumArt.Build(_scene.transform);var runner=RunnerArt.Build(_scene.transform);runner.transform.localPosition=new Vector3(shift,.66f,-.1f);runner.transform.localRotation=Quaternion.Euler(0,60,0);runner.transform.localScale=Vector3.one*1.35f;runner.Style(style>=0?style:tower==1?1:2);_camera.transform.localPosition=new Vector3(4.0f,3.1f,-12);_camera.transform.LookAt(_scene.transform.position+new Vector3(backdrop?-.3f:.45f,1.95f,.6f));_camera.backgroundColor=new Color(.89f,.83f,.69f);SetLayer(_scene.transform);}
  void ChapterSky(int chapter){string resource=chapter==1?"Art/CanalNeon-20261012":chapter==2?"Art/CanalDay-20261012":"Art/CanalSunset-20261012";var texture=Resources.Load<Texture2D>(resource);if(texture==null)return;var sky=new Material(Shader.Find("Floor/Sky")){name="OwnedLiftPreviewSky",mainTexture=texture};ArtLifetime.Own(_scene,sky);var backdrop=_camera.gameObject.AddComponent<Skybox>();backdrop.material=sky;_camera.clearFlags=CameraClearFlags.Skybox;}
  void InitializeScene(){_scene=new GameObject("Lobby3DKit");_slot=LeaseSlot();_scene.transform.position=new Vector3(1000+(_slot%8)*SlotSpacing,0,1000+(_slot/8)*SlotSpacing);
   var cameraObject=new GameObject("LobbyPreviewCamera",typeof(Camera));cameraObject.transform.SetParent(_scene.transform,false);_camera=cameraObject.GetComponent<Camera>();_camera.enabled=false;_camera.cullingMask=1<<PreviewLayer;_camera.clearFlags=CameraClearFlags.SolidColor;_camera.backgroundColor=new Color(.89f,.85f,.77f);_camera.orthographic=true;_camera.nearClipPlane=.1f;_camera.farClipPlane=40;_camera.allowHDR=false;cameraObject.transform.localPosition=new Vector3(6.5f,4.6f,-12);cameraObject.transform.LookAt(_scene.transform.position+new Vector3(0,1.7f,.2f));
   var lamp=new GameObject("PreviewSoftbox",typeof(Light));lamp.transform.SetParent(_scene.transform,false);lamp.transform.localRotation=Quaternion.Euler(32,-35,0);_key=lamp.GetComponent<Light>();_key.type=LightType.Directional;_key.intensity=1.05f;_key.color=new Color(1,.92f,.78f);_key.shadows=LightShadows.Soft;_key.shadowStrength=.45f;_key.cullingMask=1<<PreviewLayer;_key.enabled=false;
   _target=new RenderTexture(384,384,16,RenderTextureFormat.ARGB32){name="RealLiftLobbyPreview",antiAliasing=2};if(Application.isPlaying)_target.Create();_camera.targetTexture=_target;texture=_target;
  }
  static void SetLayer(Transform root){root.gameObject.layer=PreviewLayer;foreach(Transform child in root)SetLayer(child);}
  public static float CabinPreviewSize(float aspect)=>Mathf.Max(2.65f,1.55f/Mathf.Max(.2f,aspect));
  public static float CityPreviewSize(float aspect)=>Mathf.Max(6.2f,8.0f/Mathf.Max(.2f,aspect));
  void FrameAtrium(Vector2 size){if(size.x<1||size.y<1)return;bool wide=size.x>size.y;float height=wide?3.65f:4.9f;_camera.aspect=size.x/size.y;_camera.orthographicSize=height;var rotation=Quaternion.Euler(8,-4,0);float width=height*2*_camera.aspect;var focus=new Vector3(-1.4f,.66f,-.1f)+rotation*Vector3.right*(width*(.5f-(wide?.16f:.27f)))+rotation*Vector3.up*(height*(1-2*(wide?.25f:.28f)));_camera.transform.localRotation=rotation;_camera.transform.localPosition=focus-rotation*Vector3.forward*14;}
  void LateUpdate(){if(!Application.isPlaying||_camera==null)return;var size=_atriumFrame!=null?_atriumFrame.rect.size:rectTransform.rect.size;if(size.x<1||size.y<1||(_rendered&&size==_size))return;_size=size;_camera.aspect=size.x/size.y;_camera.orthographicSize=_city?CityPreviewSize(_camera.aspect):_floor?2.65f:CabinPreviewSize(_camera.aspect);
   if(_atriumFrame!=null)FrameAtrium(size);
   float pixelScale=Mathf.Min(2,(_atriumFrame!=null?1536f:768f)/Mathf.Max(size.x,size.y));int pixelsW=Mathf.Max(1,Mathf.CeilToInt(size.x*pixelScale)),pixelsH=Mathf.Max(1,Mathf.CeilToInt(size.y*pixelScale));if(_target.width!=pixelsW||_target.height!=pixelsH){_target.Release();_target.width=pixelsW;_target.height=pixelsH;_target.Create();}
   // The owned directional key exists only for this synchronous cached render.
   // No preview can light a different menu scene or the main game.
   _key.enabled=true;try{_camera.Render();_rendered=true;}finally{_key.enabled=false;}}
  protected override void OnDisable(){base.OnDisable();if(_scene!=null)_scene.SetActive(false);}
  protected override void OnEnable(){base.OnEnable();if(_scene!=null)_scene.SetActive(true);_rendered=false;}
  protected override void OnDestroy(){base.OnDestroy();texture=null;if(_camera!=null)_camera.targetTexture=null;if(_target!=null){_target.Release();Dispose(_target);}if(_scene!=null){_scene.SetActive(false);Dispose(_scene);}if(_slot>=0){Slots[_slot]=false;_slot=-1;}}
